import csv
from pathlib import Path


def answer() -> int:
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }
    balances = {}
    accounts_path = Path(__file__).parent / "dataset" / "people_accounts.csv"
    with accounts_path.open(newline="", encoding="utf-8") as accounts:
        for row in csv.DictReader(accounts):
            name = (row["first_name"], row["last_name"])
            if name in qualifying_children:
                balances[name] = int(row["account_balance"])

    if balances.keys() != qualifying_children:
        raise ValueError("A qualifying child's account was not found")
    return sum(balances.values())


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w", encoding="utf-8") as output:
        json.dump(answer(), output)
